//! Held-out evaluation: greedy exact match and the supported-vs-contradicted preference, as in
//! `reference/train_lessons.py::evaluate`. Every reply is generated by the network; teacher
//! answers are only compared against, never fed to the model (conversations replay the TRUE
//! earlier turns, like the reference).
use super::lessons::{chat_prompt, Item, Kind};
use super::Rng;
use crate::model::{Ablation, Bicameral, KvCache};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

/// Greedy reply length limit used by the reference evaluation.
pub const MAX_REPLY_TOKENS: usize = 24;

/// How far (in logits) every other token must be below an answer's next token for the GPU to
/// confirm it: far more than the GPU's and CPU's arithmetic ever differ, so an answer the GPU
/// confirms is the one the CPU would write. Closer calls are written out on the CPU.
pub const GREEDY_MARGIN: f32 = 1e-3;

/// Answers already known to be right without writing them out (the GPU confirmed that greedy
/// writing gives exactly the expected answer): (item index, answer index within the item).
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Confirmed(pub std::collections::HashSet<(usize, usize)>);

impl Confirmed {
    pub fn len(&self) -> usize {
        self.0.len()
    }
    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }
}

/// Answers the GPU can check: each one's (item, answer) index, and its row.
pub type GreedyRows = (Vec<(usize, usize)>, Vec<super::Row>);

/// The answers of `items` the GPU can check in one pass, each with its (item, answer) index and
/// its row: the prompt exactly as the reply is written after it, then the expected answer and a
/// line break as the weighted targets. Left to the CPU: actions, answers graded by a key the
/// expected answer itself does not pass, answers that do not read back exactly as written, that
/// contain a line break or are longer than a reply may be, and prompts longer than the model's
/// context.
pub fn greedy_rows(model: &Bicameral, items: &[&Item]) -> Result<GreedyRows, String> {
    let tok = &model.tokenizer;
    let newline = b'\n' as crate::tokenizer::TokenId;
    let mut keys = Vec::new();
    let mut rows = Vec::new();
    let mut add = |key: (usize, usize), prompt: &str, expected: &str| -> Result<(), String> {
        if expected.contains('\n') {
            return Ok(());
        }
        let p = tok.encode(prompt)?;
        let a = tok.encode(expected)?;
        if p.is_empty()
            || a.len() + 1 > MAX_REPLY_TOKENS
            || p.len() + a.len() > model.config.max_tokens
            || tok.decode(&a)? != expected
        {
            return Ok(());
        }
        let mut seq = p.clone();
        seq.extend(&a);
        seq.push(newline);
        let ids = seq[..seq.len() - 1].to_vec();
        let mask = (0..ids.len()).map(|i| if i + 1 >= p.len() { 1. } else { 0. }).collect();
        keys.push(key);
        rows.push(super::Row { ids, targets: seq[1..].to_vec(), mask });
        Ok(())
    };
    for (i, it) in items.iter().enumerate() {
        match it.kind {
            Kind::Prose => {}
            Kind::Conversation if it.has_actions() => {}
            Kind::Conversation => {
                let mut history = String::new();
                for (j, (user, expected)) in it.users.iter().zip(&it.replies).enumerate() {
                    history.push_str(&chat_prompt(user));
                    add((i, j), &history, expected)?;
                    history.push_str(expected);
                    history.push('\n');
                }
            }
            _ => {
                let (Some(q), Some(expected)) = (&it.prompt, &it.answer) else { continue };
                if it.key.as_ref().is_some_and(|k| !k.is_correct(expected)) {
                    continue;
                }
                let prompt = format!("{}{}", it.context.as_deref().unwrap_or(""), chat_prompt(q));
                add((i, 0), &prompt, expected)?;
            }
        }
    }
    Ok((keys, rows))
}

/// The answers of `items` the GPU confirms in GPU training (none otherwise), for
/// [`evaluate_confirmed`] with the default ablation.
pub fn confirm(trainer: &super::Trainer, model: &Bicameral, items: &[&Item]) -> Result<Confirmed, String> {
    if !trainer.on_gpu() {
        return Ok(Confirmed::default());
    }
    let (keys, rows) = greedy_rows(model, items)?;
    if rows.is_empty() {
        return Ok(Confirmed::default());
    }
    let Some(hits) = trainer.gpu_greedy(model, &rows) else { return Ok(Confirmed::default()) };
    Ok(Confirmed(keys.into_iter().zip(hits?).filter(|(_, h)| *h).map(|(k, _)| k).collect()))
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct Outcome {
    pub kind: Kind,
    pub source: String,
    pub prompt: String,
    pub expected: String,
    pub reply: String,
    pub correct: bool,
    /// Reasoning only: the model gives the supported answer a higher likelihood than the
    /// contradicted one.
    pub prefers_supported: Option<bool>,
}

#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Score {
    pub correct: usize,
    pub total: usize,
}
impl Score {
    pub fn rate(&self) -> Option<f64> {
        (self.total > 0).then(|| self.correct as f64 / self.total as f64)
    }
}

#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Report {
    /// Keys: `dialogue`, `understanding`, `reasoning`, `conv_turn` (each Nova turn).
    pub exact: BTreeMap<String, Score>,
    pub prefers_supported: Score,
    pub outcomes: Vec<Outcome>,
}
impl Report {
    pub fn overall(&self) -> Score {
        Score {
            correct: self.exact.values().map(|s| s.correct).sum(),
            total: self.exact.values().map(|s| s.total).sum(),
        }
    }
}

/// Greedy reply to `prompt`, newline-terminated replies with the trailing newline removed.
pub fn reply(model: &Bicameral, prompt: &str, max_tokens: usize, abl: Ablation) -> Result<String, String> {
    let ids = model.tokenizer.encode(prompt)?;
    let out = model.generate_cached_ids(&ids, max_tokens, abl)?;
    Ok(model.tokenizer.decode(&out)?.trim_end_matches('\n').to_string())
}

/// Sum of log-probabilities of `continuation` after `prompt` (prompt and continuation are
/// tokenized separately, like the reference `score_continuation`).
pub fn continuation_log_prob(
    model: &Bicameral,
    prompt: &str,
    continuation: &str,
    abl: Ablation,
) -> Result<f64, String> {
    let ids = model.tokenizer.encode(prompt)?;
    let answer = model.tokenizer.encode(continuation)?;
    let valid = (128 + model.tokenizer.words().len()).min(model.config.vocab);
    let mut cache = KvCache::new(model, abl);
    let mut logits = cache.prefill(model, &ids)?;
    let mut total = 0f64;
    for &a in &answer {
        let z = &logits[..valid];
        let max = z.iter().fold(f64::NEG_INFINITY, |m, &x| m.max(x as f64));
        let lse = max + z.iter().map(|&x| (x as f64 - max).exp()).sum::<f64>().ln();
        let lp = if (a as usize) < valid { z[a as usize] as f64 - lse } else { f64::NEG_INFINITY };
        total += lp.max(1e-30f64.ln());
        logits = cache.append(model, a)?;
    }
    Ok(total)
}

fn evaluate_item(
    model: &Bicameral,
    i: usize,
    it: &Item,
    abl: Ablation,
    confirmed: &Confirmed,
) -> Result<Vec<Outcome>, String> {
    let known = |j: usize| confirmed.0.contains(&(i, j));
    let mut out = Vec::new();
    match it.kind {
        Kind::Prose => {}
        Kind::Conversation if it.has_actions() => {
            // Actions and replies are each checked with the lesson's own results before them.
            for (history, expected) in it.model_turns() {
                let got = crate::nexus::next_line(model, &history, MAX_REPLY_TOKENS, abl)?;
                out.push(Outcome {
                    kind: it.kind,
                    source: it.source.clone(),
                    prompt: crate::nexus::readable(&history),
                    expected: crate::nexus::readable(expected),
                    correct: got == expected,
                    reply: crate::nexus::readable(&got),
                    prefers_supported: None,
                });
            }
        }
        Kind::Conversation => {
            let mut history = String::new();
            for (j, (user, expected)) in it.users.iter().zip(&it.replies).enumerate() {
                history.push_str(&chat_prompt(user));
                let got =
                    if known(j) { expected.clone() } else { reply(model, &history, MAX_REPLY_TOKENS, abl)? };
                out.push(Outcome {
                    kind: it.kind,
                    source: it.source.clone(),
                    prompt: history.clone(),
                    expected: expected.clone(),
                    correct: &got == expected,
                    reply: got,
                    prefers_supported: None,
                });
                history.push_str(expected);
                history.push('\n');
            }
        }
        _ => {
            let (Some(q), Some(expected)) = (&it.prompt, &it.answer) else { return Ok(out) };
            // Study Mode memories retrieved for the question come before it.
            let prompt = format!("{}{}", it.context.as_deref().unwrap_or(""), chat_prompt(q));
            let got = if known(0) { expected.clone() } else { reply(model, &prompt, MAX_REPLY_TOKENS, abl)? };
            let prefers_supported = match (&it.kind, &it.contradicted) {
                (Kind::Reasoning, Some(bad)) => Some(
                    continuation_log_prob(model, &prompt, &format!("{expected}\n"), abl)?
                        > continuation_log_prob(model, &prompt, &format!("{bad}\n"), abl)?,
                ),
                _ => None,
            };
            out.push(Outcome {
                kind: it.kind,
                source: it.source.clone(),
                prompt,
                expected: expected.clone(),
                correct: match &it.key {
                    Some(key) => key.is_correct(&got),
                    None => &got == expected,
                },
                reply: got,
                prefers_supported,
            });
        }
    }
    Ok(out)
}

/// Picks at most `limit` items per kind (deterministic for a seed); `None` keeps all.
pub fn sample_per_kind<'a>(items: &[&'a Item], limit: Option<usize>, seed: u64) -> Vec<&'a Item> {
    let Some(limit) = limit else { return items.to_vec() };
    let mut by_kind: BTreeMap<Kind, Vec<&Item>> = BTreeMap::new();
    for &it in items {
        by_kind.entry(it.kind).or_default().push(it);
    }
    let mut rng = Rng::new(seed);
    let mut out = Vec::new();
    for (_, mut group) in by_kind {
        for i in 0..group.len().min(limit) {
            let j = i + rng.below(group.len() - i);
            group.swap(i, j);
        }
        group.truncate(limit);
        out.extend(group);
    }
    out
}

/// Outcomes of each item, keyed by its position in the input.
type Indexed = Vec<(usize, Vec<Outcome>)>;

/// Evaluates the given (normally held-out) items in parallel threads.
pub fn evaluate(model: &Bicameral, items: &[&Item], abl: Ablation) -> Result<Report, String> {
    evaluate_confirmed(model, items, abl, &Confirmed::default())
}

/// [`evaluate`] where the `confirmed` answers (from [`confirm`], for this model and these
/// items, with the default ablation) are not written out again: greedy writing gives exactly
/// the expected answer, so each is recorded as that reply, right. The report is the same.
pub fn evaluate_confirmed(
    model: &Bicameral,
    items: &[&Item],
    abl: Ablation,
    confirmed: &Confirmed,
) -> Result<Report, String> {
    let threads = super::cpu_threads().min(items.len().max(1));
    let next = std::sync::atomic::AtomicUsize::new(0);
    let results: Vec<Result<Indexed, String>> = std::thread::scope(|scope| {
        let handles: Vec<_> = (0..threads)
            .map(|_| {
                scope.spawn(|| {
                    let mut done = Vec::new();
                    loop {
                        let i = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                        if i >= items.len() {
                            return Ok(done);
                        }
                        done.push((i, evaluate_item(model, i, items[i], abl, confirmed)?));
                    }
                })
            })
            .collect();
        handles.into_iter().map(|h| h.join().expect("evaluation thread panicked")).collect()
    });
    let mut indexed = Vec::new();
    for r in results {
        indexed.extend(r?);
    }
    indexed.sort_by_key(|(i, _)| *i);
    let mut report = Report::default();
    for outcome in indexed.into_iter().flat_map(|(_, o)| o) {
        let key = if outcome.kind == Kind::Conversation { "conv_turn" } else { outcome.kind.name() };
        let s = report.exact.entry(key.into()).or_default();
        s.total += 1;
        s.correct += usize::from(outcome.correct);
        if let Some(p) = outcome.prefers_supported {
            report.prefers_supported.total += 1;
            report.prefers_supported.correct += usize::from(p);
        }
        report.outcomes.push(outcome);
    }
    Ok(report)
}
